              {/* Left: Line Items List */}
              <div className="lg:col-span-7 xl:col-span-8 border-t border-border divide-y divide-border">
                {cartItems.map((item) => (
                  <div key={item.id} className="py-2 sm:py-4">
                    <CartLineItem item={item} />
