import { useState, useEffect } from 'react';
import { useNavigate, useLocation, Link } from 'react-router-dom';
import useCustomer from '../../../shared/hooks/useCustomer';
import TextInput from '../../../shared/components/TextInput';
import { Button } from '../../../shared/components/Button';
import Seo from '../../../shared/components/Seo';

export const CustomerAuthPage = ({ defaultMode = 'login' }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const { customer, isAuthenticated, login, register, loginWithOtp } = useCustomer();

  const [mode, setMode] = useState(defaultMode); // 'login' | 'register' | 'otp'
  const [form, setForm] = useState({ name: '', email: '', password: '', phone: '' });
  const [otpPhone, setOtpPhone] = useState('');
  const [otpCode, setOtpCode] = useState('');
  const [otpStep, setOtpStep] = useState('phone'); // 'phone' | 'code'
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [info, setInfo] = useState('');

  useEffect(() => {
    if (isAuthenticated) {
      const from = location.state?.from || '/account';
      navigate(from, { replace: true });
    }
  }, [isAuthenticated, navigate, location]);

  useEffect(() => {
    setMode(defaultMode);
    setError('');
    setInfo('');
  }, [defaultMode]);

  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setInfo('');
    setBusy(true);

    try {
      if (mode === 'login') {
        const res = await login(form.email.trim(), form.password);
        if (!res.success) {
          setError(res.message || 'Invalid email or password.');
        }
      } else if (mode === 'register') {
        if (!form.name.trim() || form.name.trim().length < 2) {
          setError('Please provide your full name.');
          setBusy(false);
          return;
        }
        const res = await register(form.name.trim(), form.email.trim(), form.password, form.phone.trim());
        if (!res.success) {
          setError(res.message || 'Could not complete registration.');
        }
      }
    } catch (err) {
      setError(err?.message || 'Authentication failed. Please try again.');
    } finally {
      setBusy(false);
    }
  };

  const handleSendOtp = async (e) => {
    e.preventDefault();
    setError('');
    setInfo('');
    if (!otpPhone.trim()) {
      setError('Please enter your phone number.');
      return;
    }
    setBusy(true);
    try {
      // In development/test mode, simulated SMS delivery works
      setInfo('Verification code sent to ' + otpPhone);
      setOtpStep('code');
    } catch (err) {
      setError(err?.message || 'Could not send verification code.');
    } finally {
      setBusy(false);
    }
  };

  const handleVerifyOtp = async (e) => {
    e.preventDefault();
    setError('');
    setBusy(true);
    try {
      const res = await loginWithOtp(otpPhone.trim(), otpCode.trim());
      if (!res.success) {
        setError(res.message || 'Invalid or expired verification code.');
      }
    } catch (err) {
      setError(err?.message || 'Verification failed.');
    } finally {
      setBusy(false);
    }
  };

  const isRegister = mode === 'register';

  return (
    <div className="w-full bg-surface min-h-[70vh] flex items-center justify-center py-16 px-5 sm:px-8">
      <Seo
        title={isRegister ? 'Create Account · Sabr Studio' : 'Customer Sign In · Sabr Studio'}
        description="Access your Sabr Studio customer account, order history, and design consultations."
        noIndex
      />

      <div className="max-w-md w-full bg-white border border-border rounded-md p-8 sm:p-10 shadow-xs space-y-6">
        <div className="text-center space-y-2">
          <span className="w-12 h-12 rounded-full bg-surface border border-border flex items-center justify-center text-ink mx-auto mb-3">
            <LuUser className="w-5 h-5" />
          </span>
          <h1 className="font-abhaya text-3xl font-medium text-ink">
            {isRegister ? 'Join Sabr Studio' : mode === 'otp' ? 'Phone Sign In' : 'Welcome Back'}
          </h1>
          <p className="font-inter text-xs text-muted">
            {isRegister
              ? 'Create an account to track orders and save your delivery details.'
              : mode === 'otp'
              ? 'Receive a one-time verification code via SMS.'
              : 'Log in to view orders, invoices and saved addresses.'}
          </p>
        </div>

        {/* Tab switch between email login and register */}
        {mode !== 'otp' && (
          <div className="flex border-b border-border text-xs uppercase tracking-wider font-medium text-center">
            <button
              type="button"
              onClick={() => { setMode('login'); setError(''); setInfo(''); }}
              className={`flex-1 py-2.5 transition-colors border-b-2 ${
                mode === 'login'
                  ? 'border-black text-black font-semibold'
                  : 'border-transparent text-muted hover:text-black'
              }`}
            >
              Sign In
            </button>
            <button
              type="button"
              onClick={() => { setMode('register'); setError(''); setInfo(''); }}
              className={`flex-1 py-2.5 transition-colors border-b-2 ${
                mode === 'register'
                  ? 'border-black text-black font-semibold'
                  : 'border-transparent text-muted hover:text-black'
              }`}
            >
              Register
            </button>
          </div>
        )}

        {error && (
          <div className="p-3 text-xs text-error bg-error/5 border border-error/20 rounded-sm">
            {error}
          </div>
        )}
        {info && (
          <div className="p-3 text-xs text-ink bg-surface border border-border rounded-sm">
            {info}
          </div>
        )}

        {mode === 'otp' ? (
          <form onSubmit={otpStep === 'phone' ? handleSendOtp : handleVerifyOtp} className="space-y-4">
            {otpStep === 'phone' ? (
              <TextInput
                id="otp-phone"
                label="Phone Number"
                type="tel"
                required
                placeholder="+91 98765 43210"
                value={otpPhone}
                onChange={(e) => setOtpPhone(e.target.value)}
              />
            ) : (
              <TextInput
                id="otp-code"
                label="Verification Code"
                type="text"
                required
                placeholder="6-digit code"
                maxLength={6}
                value={otpCode}
                onChange={(e) => setOtpCode(e.target.value)}
              />
            )}

            <Button
              type="submit"
              variant="Primary"
              fullWidth
              disabled={busy}
              label={busy ? 'Verifying…' : otpStep === 'phone' ? 'Send Code' : 'Verify & Sign In'}
            />

            <div className="text-center pt-2">
              <button
                type="button"
                onClick={() => { setMode('login'); setOtpStep('phone'); setError(''); setInfo(''); }}
                className="text-xs text-muted hover:text-ink underline"
              >
                Sign in with email instead
              </button>
            </div>
          </form>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-4">
            {isRegister && (
              <TextInput
                id="cust-name"
                label="Full Name"
                type="text"
                required
                placeholder="Rohit Sharma"
                value={form.name}
                onChange={set('name')}
              />
            )}

            <TextInput
              id="cust-email"
              label="Email Address"
              type="email"
              required
              placeholder="rohit@example.com"
              value={form.email}
              onChange={set('email')}
            />

            {isRegister && (
              <TextInput
                id="cust-phone"
                label="Phone (optional)"
                type="tel"
                placeholder="+91 98765 43210"
                value={form.phone}
                onChange={set('phone')}
              />
            )}

            <TextInput
              id="cust-password"
              label="Password"
              type="password"
              required
              placeholder="••••••••"
              value={form.password}
              onChange={set('password')}
            />

            <Button
              type="submit"
              variant="Primary"
              fullWidth
              disabled={busy}
              label={busy ? 'Please wait…' : isRegister ? 'Create Account' : 'Sign In'}
            />

            <div className="flex items-center justify-between pt-2 text-xs text-muted">
              <button
                type="button"
                onClick={() => { setMode('otp'); setError(''); setInfo(''); }}
                className="inline-flex items-center gap-1 hover:text-ink"
              >
                <LuSmartphone className="w-3.5 h-3.5" /> Sign in via SMS
              </button>
              <Link to="/contact" className="hover:text-ink underline">
                Need help?
              </Link>
            </div>
          </form>
        )}
      </div>
    </div>
  );
};

export default CustomerAuthPage;

import { useState, useEffect, useRef } from 'react';
import { motion, useScroll, useTransform, useSpring } from 'framer-motion';
import { homeHeroData } from '../data/homeHero.data';
import { Button } from '../../../shared/components/Button';
import { useReducedMotion } from '../../../shared/hooks/useReducedMotion';
import { mountFadeProps } from '../../../shared/animations/reveal';
import { buildCloudinaryUrl } from '../../../shared/utils/buildCloudinaryUrl';

export const HeroSlider = () => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const reducedMotion = useReducedMotion();
  const sectionRef = useRef(null);
  const { slides, eyebrow, title, description, primaryCta, secondaryCta } = homeHeroData;

  useEffect(() => {
    if (reducedMotion) {
      setCurrentSlide(0);
      return undefined;
    }
    const timer = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % slides.length);
    }, 6000);

    return () => clearInterval(timer);
  }, [slides.length, reducedMotion]);

  // Mount-only Hero entry: plays once on page mount, never on scroll or slide
  // change. Slide changes swap images only — copy stays stable (no replay).
  const heroEnter = mountFadeProps(reducedMotion, 0.05);
  const ctaEnter = mountFadeProps(reducedMotion, 0.2);

  // Slow scroll-linked parallax: background drifts gently as the user scrolls
  // (GPU transform via motion value — no React state per frame). The raw scroll
  // progress is run through a spring so movement lags softly behind the wheel:
  // this removes jitter/stutter and reads as slow + gradual rather than snappy,
  // while staying clearly noticeable. Disabled entirely under reduced motion.
  const { scrollYProgress } = useScroll({
    target: sectionRef,
    offset: ['start start', 'end start'],
  });
  const smoothProgress = useSpring(scrollYProgress, {
    stiffness: 70,
    damping: 18,
    mass: 0.6,
  });
  const bgY = useTransform(smoothProgress, [0, 1], ['0%', '14%']);
  const contentY = useTransform(smoothProgress, [0, 1], ['0%', '-9%']);
  const contentOpacity = useTransform(smoothProgress, [0, 0.9], [1, 0.4]);

  return (
    <section
      ref={sectionRef}
      className="relative w-full min-h-[100svh] flex items-center justify-center overflow-hidden overflow-x-clip bg-black"
      aria-label="Sabr Studio Introduction"
    >
      {/* Background Images: horizontal slide track (transform translate), both images stay mounted/preloaded */}
      <motion.div
        aria-hidden="true"
        style={reducedMotion ? undefined : { y: bgY }}
        className="absolute inset-0 z-0 will-change-transform"
      >
        <div
          className={`flex h-full w-full will-change-transform ${
            reducedMotion ? '' : 'transition-transform duration-700 ease-in-out'
          }`}
          style={{ transform: `translate3d(-${currentSlide * 100}%, 0, 0)` }}
        >
          {slides.map((slide, index) => (
            <div key={slide.id} className="relative h-full w-full shrink-0">
              <img
                src={buildCloudinaryUrl(slide.image, { width: 1920, height: 1080 })}
                alt="Sabr Studio interior architecture showcase"
                loading="eager"
                fetchpriority={index === 0 ? 'high' : 'auto'}
                width="1920"
                height="1080"
                className="w-full h-full object-cover object-center"
              />
            </div>
          ))}
        </div>
      </motion.div>

      {/* 40% Black Overlay (UI-UX §29) — static, above images, below content */}
      <div className="absolute inset-0 bg-black/40 z-10" aria-hidden="true" />

      {/* Hero Content Shell */}
      <motion.div
        style={reducedMotion ? undefined : { y: contentY, opacity: contentOpacity }}
        className="relative z-20 max-w-container-wide mx-auto px-5 sm:px-8 lg:px-12 w-full max-w-full text-center text-white py-12 sm:py-16"
      >
        <motion.div
          {...heroEnter}
          className="max-w-3xl mx-auto space-y-6 sm:space-y-8"
        >
          <span className="block text-xs sm:text-sm uppercase tracking-widest font-inter font-medium text-white/80">
            {eyebrow}
          </span>

          <h1 className="font-abhaya text-4xl sm:text-6xl lg:text-7xl font-medium tracking-tight leading-[1.08] text-white">
            {title}
          </h1>

          <p className="font-inter text-sm sm:text-base lg:text-lg text-white/90 leading-relaxed max-w-content mx-auto font-normal">
            {description}
          </p>

          <motion.div
            {...ctaEnter}
            className="pt-4 flex flex-col sm:flex-row items-center justify-center gap-4"
          >
            <Button
              to={primaryCta.to}
              variant="White"
              size="default"
              label={primaryCta.label}
              className="w-full sm:w-auto min-w-[180px]"
            />
            <Button
              to={secondaryCta.to}
              variant="WhiteOutline"
              size="default"
              label={secondaryCta.label}
              className="w-full sm:w-auto min-w-[180px]"
            />
          </motion.div>
        </motion.div>
      </motion.div>
    </section>
  );
};

export default HeroSlider;

import { useState, useEffect } from 'react';
import { formatPrice } from '../../../shared/utils/formatPrice';
import { Button } from '../../../shared/components/Button';
import Seo from '../../../shared/components/Seo';
import Skeleton from '../../../shared/components/Skeleton';
import ErrorState from '../../../shared/components/ErrorState';
import { getMyOrder } from '../../cart/api/checkout.api';
import { LuCircleCheck, LuMapPin, LuTruck } from 'react-icons/lu';

function fmtAddr(a) {
  if (!a) return '';
  return [a.house, a.street, a.landmark, a.city, a.state, a.pincode, a.country].filter(Boolean).join(', ');
}

export const OrderSuccess = () => {
  const { orderNumber } = useParams();
  const { state } = useLocation();
  const [order, setOrder] = useState(state?.order || null);
  const [loading, setLoading] = useState(!state?.order);
  const [error, setError] = useState('');
  useEffect(() => {
    if (state?.order || !orderNumber) return;
    setLoading(true);
    getMyOrder(orderNumber).then((res) => setOrder(res?.data || null)).catch((e) => setError(e?.message || 'Could not load order.')).finally(() => setLoading(false));
  }, [orderNumber]);
  if (loading) return <div className="max-w-container mx-auto px-5 py-16 space-y-4"><Skeleton height="32px" width="60%" /><Skeleton height="240px" /></div>;
  if (error || !order) return <div className="max-w-container mx-auto px-5 py-16"><ErrorState title="Order not found" message={error || 'This order is not linked to your account.'} /></div>;
  const addr = order.deliveryAddress || {};
  return (
    <div className="w-full bg-white">
      <Seo title={`Order ${order.orderNumber} confirmed · Sabr Studio`} />
