import React, { createContext, useState, useEffect, useCallback } from 'react';

export const CartContext = createContext(null);

const STORAGE_KEY = 'sabr_cart_v1';

// Canonical product identity: Mongo docs expose `_id` only via .lean()
// (no virtual `id`), while in-memory/seed items expose `id`/`_id`/`slug`
// interchangeably. Compare all three as strings (ObjectId vs string safe)
const getProductKey = (product) =>
  String(product?.id ?? product?._id ?? product?.slug ?? '');

function loadPersistedCart() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.filter((i) => i && (i.id || i._id || i.slug)) : [];
  } catch { return []; }
}

export const CartProvider = ({ children }) => {
  // Persisted across refresh (fixes lost-cart on login/address/Razorpay steps)
  const [cartItems, setCartItems] = useState(loadPersistedCart);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);

  useEffect(() => {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(cartItems)); } catch {}
  }, [cartItems ]);

  const openDrawer = () => setIsDrawerOpen(true);
  const closeDrawer = () => setIsDrawerOpen(false);
  const toggleDrawer = () => setIsDrawerOpen((prev) => !prev);

  // Canonical product identity: Mongo docs expose `_id` only via .lean()
  // (no virtual `id`), while in-memory/seed items expose `id`/`_id`/`slug`
  // interchangeably. Compare all three as strings (ObjectId vs string safe)
  // so the same product arriving from different API responses is never
  // duplicated. Never use object identity.
  const getProductKey = (product) =>
    String(product?.id ?? product?._id ?? product?.slug ?? '');

  const matchesKey = (item, key) => key !== '' && getProductKey(item) === key;

  const matchesId = (item, productId) => {
    const target = String(productId ?? '');
    return (
      String(item.id ?? '') === target ||
      String(item._id ?? '') === target ||
      String(item.slug ?? '') === target
    );
  };

  const addToCart = (product, quantity = 1) => {
    const key = getProductKey(product);
    const normalizedId = product?.id ?? product?._id ?? product?.slug;
    setCartItems((prev) => {
      // Same product already in cart → increase its quantity, never duplicate.
      if (key && prev.some((item) => matchesKey(item, key))) {
        return prev.map((item) =>
          matchesKey(item, key)
            ? { ...item, quantity: item.quantity + quantity }
            : item
        );
      }
      return [...prev, { ...product, id: normalizedId, quantity }];
    });
  };

  const removeFromCart = (productId) => {
    setCartItems((prev) => prev.filter((item) => !matchesId(item, productId)));
  };

  const updateQuantity = (productId, quantity) => {
    // Minimum quantity is 1: minus at 1 does nothing; ONLY Remove deletes.
    if (quantity < 1) {
      return;
    }
    setCartItems((prev) =>
      prev.map((item) => (matchesId(item, productId) ? { ...item, quantity } : item))
    );
  };

  const clearCart = () => {
    setCartItems([]);
  };

  // Remove ONLY purchased items after verified payment (never whole-cart on failure).
  const removePurchasedItems = useCallback((purchasedIds) => {
    const set = new Set((purchasedIds || []).map((x) => String(x)));
    if (!set.size) return;
    setCartItems((prev) => prev.filter((item) => {
      const keys = [item.id, item._id, item.slug, item.itemId, item.productId].filter(Boolean).map(String);
      return !keys.some((k) => set.has(k));
    }));
  }, []);

  // Badge = UNIQUE products only (never sum of quantities).
  const cartCount = cartItems.length;
  const cartTotal = cartItems.reduce((sum, item) => sum + (Number(item.price) || 0) * item.quantity, 0);

  return (
    <CartContext.Provider
      value={{
        cartItems,
        addToCart,
        removeFromCart,
        updateQuantity,
        clearCart,
        removePurchasedItems,
        cartCount,
        cartTotal,
        isDrawerOpen,
        openDrawer,
        closeDrawer,
        toggleDrawer,
      }}
    >
      {children}
    </CartContext.Provider>
  );
};

export const useCart = () => {
  const context = React.useContext(CartContext);
  if (!context) {
    throw new Error('useCart must be used within a CartProvider');
  }
  return context;
};

export default CartProvider;

import { createContext, useState, useEffect, useCallback } from 'react';
import axiosClient from '../api/axiosClient';

export const CustomerContext = createContext(null);

export const CustomerProvider = ({ children }) => {
  const [customer, setCustomer] = useState(null);
  const [loading, setLoading] = useState(true);

  const checkAuth = useCallback(async () => {
    try {
      const res = await axiosClient.get('/customer/me');
      const data = res?.data?.customer || null;
      if (res?.success && data) setCustomer(data);
      else setCustomer(null);
    } catch { setCustomer(null); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { checkAuth(); }, [checkAuth]);

  const login = async (email, password) => {
    try {
      const res = await axiosClient.post('/customer/login', { email, password });
      const data = res?.data?.customer || null;
      if (res?.success && data) { setCustomer(data); return { success: true }; }
      return { success: false, message: res?.message || 'Login failed' };
    } catch (err) { return { success: false, message: err?.message || 'Invalid credentials' }; }
  };

  const register = async (payload) => {
    try {
      const res = await axiosClient.post('/customer/register', payload);
      const data = res?.data?.customer || null;
      if (res?.success && data) { setCustomer(data); return { success: true }; }
      return { success: false, message: res?.message || 'Registration failed' };
    } catch (err) { return { success: false, message: err?.message || 'Registration failed' }; }
  };

  const googleLogin = async (credential) => {
    try {
      // Send ONLY the opaque Google ID token; the backend verifies it server-side.
      const res = await axiosClient.post('/customer/google', { credential });
      const data = res?.data?.customer || null;
      if (res?.success && data) { setCustomer(data); return { success: true }; }
      return { success: false, message: res?.message || 'Google login failed' };
    } catch (err) { return { success: false, message: err?.message || 'Google login failed' }; }
  };

  const loginWithOtp = async (phone, code) => {
    try {
      const res = await axiosClient.post('/customer/verify-otp', { phone, code });
      const data = res?.data?.customer || null;
      if (res?.success && data) { setCustomer(data); return { success: true }; }
      return { success: false, message: res?.message || 'OTP verification failed' };
    } catch (err) { return { success: false, message: err?.message || 'OTP verification failed' }; }
  };

  const logout = async () => {
    try { await axiosClient.post('/customer/logout'); } catch {}
    finally { setCustomer(null); }
  };

  const updateProfile = async (payload) => {
    try {
      const res = await axiosClient.put('/customer/profile', payload);
      const data = res?.data?.customer || null;
      if (res?.success && data) { setCustomer(data); return { success: true, customer: data }; }
      return { success: false, message: res?.message || 'Profile update failed' };
    } catch (err) { return { success: false, message: err?.message || 'Profile update failed' }; }
  };

  return (
    <CustomerContext.Provider value={{ customer, setCustomer, loading, isAuthenticated: Boolean(customer), login, register, googleLogin, loginWithOtp, logout, updateProfile, checkAuth }}>
      {children}
    </CustomerContext.Provider>
  );
};

export default CustomerProvider;
